import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as n,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MiniMax Agent learning map","description":"MiniMax Agent is the general-purpose agent workbench, not MiniMax Code. This directory covers the web workbench only. Code / Hailuo / Talkie stay one row on the family map.","frontmatter":{"title":"MiniMax Agent learning map","description":"MiniMax Agent is the general-purpose agent workbench, not MiniMax Code. This directory covers the web workbench only. Code / Hailuo / Talkie stay one row on the family map.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/minimax-agent/index.md","filePath":"products/minimax-agent/index.md","lastUpdated":1787107158000}'),r={name:"products/minimax-agent/index.md"};function s(o,a,l,d,m,h){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="minimax-agent-learning-map" tabindex="-1">MiniMax Agent learning map <a class="header-anchor" href="#minimax-agent-learning-map" aria-label="Permalink to &quot;MiniMax Agent learning map&quot;">​</a></h1><blockquote><p><strong>MiniMax Agent</strong> is MiniMax&#39;s general-purpose agent workbench. The official launch post (<a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">Agent</a>) calls it a general agent that can finish <strong>long-horizon</strong> tasks: plan an expert solution, break the work down, run sub-tasks, and deliver a result.</p><p>China entry: <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>. International entry: <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a>.</p><p><strong>This directory is not a MiniMax Code tutorial.</strong> The desktop coding agent lives at the official <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code welcome page</a>. This site tracks Code in issue #72.</p></blockquote><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>The company site, the Agent site, and the docs site reuse several names. They are <strong>not</strong> one product with four skins. The <strong>core path</strong> here is <strong>MiniMax Agent</strong> (the web workbench).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MiniMax family</span></span>
<span class="line"><span>├── MiniMax Agent — general-purpose workbench (this directory)</span></span>
<span class="line"><span>│   ├── Web: agent.minimaxi.com / agent.minimax.io</span></span>
<span class="line"><span>│   ├── Lightning / Pro modes</span></span>
<span class="line"><span>│   ├── Skill marketplace /skills</span></span>
<span class="line"><span>│   └── On-site entries: MaxHermes, MaxClaw</span></span>
<span class="line"><span>├── MiniMax Code — desktop coding agent (#72, not expanded here)</span></span>
<span class="line"><span>├── MiniMax Design / Hub — multimodal creation canvas</span></span>
<span class="line"><span>├── Hailuo — video generation</span></span>
<span class="line"><span>├── MiniMax Audio — speech and music</span></span>
<span class="line"><span>├── Xingye / Talkie — character / community apps</span></span>
<span class="line"><span>└── Open Platform / Token Plan — API and billing</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Official first-level entry</th><th>What it is</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>MiniMax Agent</strong></td><td>Long-horizon general agent workbench</td><td><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a></td><td>Standalone pages in this directory</td></tr><tr><td>MiniMax Code</td><td>Desktop AI agent for a local project / terminal / browser</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code welcome</a></td><td>One row. Main tutorial is #72</td></tr><tr><td>MiniMax Design / Hub</td><td>Multimodal creation studio. EN About still says Hub; <code>hub.minimaxi.com</code> now loads Design</td><td><a href="https://design.minimaxi.com/" target="_blank" rel="noreferrer">design.minimaxi.com</a>, <a href="https://hub.minimaxi.com/" target="_blank" rel="noreferrer">hub.minimaxi.com</a></td><td>One row</td></tr><tr><td>Hailuo</td><td>Text / image to video</td><td><a href="https://hailuoai.com/" target="_blank" rel="noreferrer">hailuoai.com</a></td><td>One row</td></tr><tr><td>MiniMax Audio</td><td>Speech and music</td><td><a href="https://www.minimaxi.com/audio" target="_blank" rel="noreferrer">minimaxi.com/audio</a></td><td>One row</td></tr><tr><td>Xingye (星野)</td><td>Immersive agent community (China)</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td><td>One row</td></tr><tr><td>Talkie</td><td>Xingye&#39;s overseas counterpart</td><td><a href="https://www.talkie-ai.com/" target="_blank" rel="noreferrer">talkie-ai.com</a></td><td>One row</td></tr><tr><td>Open Platform / API</td><td>Model HTTP API</td><td><a href="https://platform.minimaxi.com/" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td><td>One row</td></tr><tr><td>Token Plan</td><td>Subscription and quota</td><td>Product nav on the company site</td><td>One row</td></tr><tr><td>About / News / IR</td><td>Company pages</td><td><a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">minimaxi.com</a></td><td>Out of scope</td></tr></tbody></table><p>Sources: <a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">www.minimaxi.com</a> About, <a href="https://www.minimaxi.com/en" target="_blank" rel="noreferrer">www.minimaxi.com/en</a> Product / About, <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>, <a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">docs/llms.txt</a>. Opened 2026-08-19.</p><p><strong>Names that collide:</strong></p><ul><li><strong>MiniMax Agent ≠ MiniMax Code.</strong> Agent is the general workbench. Code is the desktop app. Changelog <a href="https://agent.minimaxi.com/docs/changelog" target="_blank" rel="noreferrer">v3.0.33</a>: &quot;Desktop app officially renamed to MiniMax Code.&quot;</li><li><strong>MiniMax Hub ≠ MiniMax Agent.</strong> EN About lists Hub next to Code / Audio / Talkie. Opening <code>hub.minimaxi.com</code> currently loads MiniMax Design.</li><li><strong>Mini-Agent ≠ MiniMax Agent.</strong> <code>MiniMax-AI/Mini-Agent</code> is an open-platform sample, not this product.</li><li><strong>MaxHermes / MaxClaw</strong> appear on the Agent home page. They are not company first-level products. See the <a href="./minimax-agent-glossary.html">glossary</a>.</li></ul><p>Model internals (MSA, attention, training) belong in <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>. This directory does not explain them.</p><h3 id="quick-decision-which-surface" tabindex="-1">Quick decision: which surface? <a class="header-anchor" href="#quick-decision-which-surface" aria-label="Permalink to &quot;Quick decision: which surface?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do I want to do?</span></span>
<span class="line"><span>├── Finish a long task in the browser (research, PPT, report, site, multimodal deliverable)</span></span>
<span class="line"><span>│   └── → MiniMax Agent (this directory)</span></span>
<span class="line"><span>│       ├── Q&amp;A / light search / light code → Lightning</span></span>
<span class="line"><span>│       └── Long research / full-stack / PPT / report / site → Pro; turn on Agent Team when the work must split</span></span>
<span class="line"><span>├── Edit a local repo, inspect diffs, run a terminal</span></span>
<span class="line"><span>│   └── → MiniMax Code (official desktop docs; this site #72)</span></span>
<span class="line"><span>├── Only generate video</span></span>
<span class="line"><span>│   └── → Hailuo</span></span>
<span class="line"><span>├── Only speech / music</span></span>
<span class="line"><span>│   └── → MiniMax Audio</span></span>
<span class="line"><span>├── Character roleplay / community</span></span>
<span class="line"><span>│   └── → Xingye (China) / Talkie (overseas)</span></span>
<span class="line"><span>├── Storyboard-to-film canvas</span></span>
<span class="line"><span>│   └── → MiniMax Design (the domain may still say Hub)</span></span>
<span class="line"><span>└── Call models from my own software</span></span>
<span class="line"><span>    └── → Open Platform API</span></span></code></pre></div><h2 id="when-minimax-agent-is-worth-a-try" tabindex="-1">When MiniMax Agent is worth a try <a class="header-anchor" href="#when-minimax-agent-is-worth-a-try" aria-label="Permalink to &quot;When MiniMax Agent is worth a try&quot;">​</a></h2><p><strong>Try it when:</strong></p><ul><li>You want a <strong>browser deliverable</strong>: research, slides, a report, a site — not a terminal session over a repo.</li><li>You already use a Claude.ai / Cowork-style workbench and want the China / MiniMax entry.</li><li>The job needs multimodal output or MCP. The <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">launch post</a> lists programming, multimodality, and MCP as design bars.</li></ul><p><strong>Wait when:</strong></p><ul><li>You need a local project, a terminal, and a git workspace — that is <strong>MiniMax Code</strong>.</li><li>You only need one video — use Hailuo.</li><li>You want a companion character — use Xingye / Talkie.</li><li>You need a copy-paste command / flag manual — there is no official Commands page for the Agent web workbench. This site only records wording we can open.</li></ul><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Open it</td><td><a href="./minimax-agent.html">MiniMax Agent tutorial</a></td><td>Sign in and send the first task</td></tr><tr><td>2. Pick a mode</td><td>Lightning / Pro in the tutorial, then the <a href="./minimax-agent-cookbook.html">Cookbook</a></td><td>Short Q&amp;A stays off Pro</td></tr><tr><td>3. Skills and Team</td><td>Cookbook + <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skill marketplace</a></td><td>When to install a skill; when to open Team</td></tr><tr><td>4. Look up entries</td><td><a href="./minimax-agent-cheatsheet.html">Cheatsheet</a></td><td>Domains, modes, sources</td></tr><tr><td>5. Untangle names</td><td><a href="./minimax-agent-glossary.html">Glossary</a></td><td>Agent / Code / Hub / Design / Mini-Agent</td></tr></tbody></table><h2 id="feature-snapshot" tabindex="-1">Feature snapshot <a class="header-anchor" href="#feature-snapshot" aria-label="Permalink to &quot;Feature snapshot&quot;">​</a></h2><p>Only capabilities with official wording.</p><table tabindex="0"><thead><tr><th>Capability</th><th>One line</th><th>Official source</th></tr></thead><tbody><tr><td>Long-horizon tasks</td><td>Plan, split, deliver a final result</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">Launch post</a></td></tr><tr><td>Lightning</td><td>Fast Q&amp;A / light search / light code</td><td><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a></td></tr><tr><td>Pro</td><td>Deep research / full-stack / PPT / reports / websites</td><td><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a></td></tr><tr><td>Agent Team</td><td>Lead agent splits work; Leader / Worker / Verifier</td><td><a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a></td></tr><tr><td>Skill marketplace</td><td>Browse, install, create, or import from GitHub</td><td><a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a></td></tr><tr><td>Programming</td><td>Complex flows, simulated user tests, UI quality</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">Launch post</a></td></tr><tr><td>Multimodal</td><td>Long text / video / audio / image; built-in generation</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">Launch post</a></td></tr><tr><td>MCP</td><td>Built-in MiniMax MCP; also lists GitHub / GitLab / Slack / Figma</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">Launch post</a></td></tr><tr><td>Writing / voice / image / docs / translate</td><td>Consumer feature page</td><td><a href="https://agent.minimax.io/features/en.html" target="_blank" rel="noreferrer">features</a></td></tr></tbody></table><p>The driving model changes. The home page on 2026-08-19 showed MiniMax-M3. Internals: <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li>Product: <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">https://agent.minimaxi.com/</a></li><li>International: <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">https://agent.minimax.io/</a></li><li>Company: <a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">https://www.minimaxi.com/</a></li><li>Docs index: <a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">https://agent.minimaxi.com/docs/llms.txt</a></li><li>Full source list: <a href="./minimax-agent-cheatsheet.html#high-quality-sources">cheatsheet</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./minimax-agent.html">MiniMax Agent tutorial</a></li><li><a href="./minimax-agent-cookbook.html">Cookbook</a></li><li><a href="./minimax-agent-cheatsheet.html">Cheatsheet</a></li><li><a href="./minimax-agent-glossary.html">Glossary</a></li><li><a href="./../">All products</a></li></ul>`,27)])])}const x=e(r,[["render",s]]);export{f as __pageData,x as default};
